-- как обложка/первое фото статьи, остальные два — в тело статьи.

-- 1. Фото локаций в маршруте + ссылка на статью (article_slug).
update tours set itinerary = '[
  {"day": 1, "title": {"ru": "Капибары и вьетнамский кофе", "en": null}, "description": {"ru": "Знакомство с капибарами и кофе через традиционный фильтр фин.", "en": null}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/kapibary-i-kofe-nyachang/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/kapibary-i-kofe-nyachang/2.jpg", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/kapibary-i-kofe-nyachang/3.png"], "article_slug": "kapibary-i-kofe-nyachang"},
  {"day": 1, "title": {"ru": "Башня Куанг-Минь", "en": null}, "description": {"ru": "Новая золотая 13-ярусная башня на горе Фыонг Хоанг; вид на Нячанг, бухту, острова и побережье.", "en": null}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashnya-kuang-min/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashnya-kuang-min/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashnya-kuang-min/3.png"], "article_slug": "bashnya-kuang-min"},
  {"day": 1, "title": {"ru": "Пагода Лонгшон", "en": null}, "description": {"ru": "Белый Будда и буддийская история города; подъезжаем к верхней части комплекса на автомобиле.", "en": null}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/pagoda-longshon/1.jpg", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/pagoda-longshon/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/pagoda-longshon/3.jpg"], "article_slug": "pagoda-longshon"},
  {"day": 1, "title": {"ru": "Кафедральный собор Христа-Царя", "en": null}, "description": {"ru": "Каменный неоготический собор французской эпохи, витражи и колокольня.", "en": null}},
  {"day": 1, "title": {"ru": "Башни По Нагар", "en": null}, "description": {"ru": "Наследие древнего Чамского королевства VII–XIII веков.", "en": null}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashni-po-nagar/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashni-po-nagar/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashni-po-nagar/3.png"], "article_slug": "bashni-po-nagar"},
  {"day": 1, "title": {"ru": "Хон Чонг", "en": null}, "description": {"ru": "Гранитная формация, легенда о великане и «муже с женой», культурный павильон.", "en": null}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/hon-chong/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/hon-chong/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/hon-chong/3.png"], "article_slug": "hon-chong"},
  {"day": 1, "title": {"ru": "Музей Александра Йерсена", "en": null}, "description": {"ru": "История учёного и Института Пастера в Нячанге.", "en": null}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/muzey-aleksandra-yersena/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/muzey-aleksandra-yersena/2.png"], "article_slug": "muzey-aleksandra-yersena"},
  {"day": 1, "title": {"ru": "Обед в кафе с вертолётом", "en": null}, "description": {"ru": "Гости выбирают блюда под себя; заказ оплачивается по факту.", "en": null}, "photos": ["https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/obed-v-kafe-s-vertoletom/1.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/obed-v-kafe-s-vertoletom/2.png", "https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/obed-v-kafe-s-vertoletom/3.png"], "article_slug": "obed-v-kafe-s-vertoletom"}
]'::jsonb
where slug = 'nyachang-avtorskiy';

