-- 3. Статьи блога (СЕО-гайды) — is_published сразу true (рабочая фича).
insert into articles (slug, title, destination, excerpt, cover_image_url, body, related_tour_id, is_published, published_at)
select
  v.slug, v.title, 'nyachang', v.excerpt, v.cover_image_url, v.body,
  (select id from tours where slug = 'nyachang-avtorskiy'),
  true, now()
from (values

  ('kapibary-i-kofe-nyachang', 'Капибары и вьетнамский кофе: неожиданное свидание в Нячанге',
   'Самый спокойный зверь на планете и самый крепкий кофе Юго-Восточной Азии — почему это работает.',
   'https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/kapibary-i-kofe-nyachang/1.png',
$body1$Капибара — самый крупный грызун на Земле, родом из Южной Америки, но в последние годы она стала кем-то вроде неофициального символа отдыха: в интернете капибар называют «самыми расслабленными животными», которые одинаково спокойно сидят и в реке, и на коленях у крокодила, и рядом с человеком. Нячанг подхватил этот тренд одним из первых во Вьетнаме — здесь капибары живут не в зоопарке, а в обычном городском кафе, куда можно зайти с улицы.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/kapibary-i-kofe-nyachang/1.png | Капибара на веранде кафе, рядом — традиционный вьетнамский кофе фин]

Животных здесь не боятся и не прячут: капибары свободно расхаживают между столиками, разрешают себя гладить и без особого интереса, но и без напряжения принимают угощение из рук. Для грызуна весом под полсотни килограммов это удивительное дружелюбие — собственно, ради него сюда и приходят.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/kapibary-i-kofe-nyachang/2.jpg | Капибара крупным планом на фоне кафе]

Вторая часть свидания — кофе. Вьетнам занимает второе место в мире по экспорту кофе после Бразилии, и почти весь этот путь страна проделала за одно столетие: кофейные деревья привезли французские колонисты в XIX веке, а сорт робуста, который здесь выращивают массово, дал начало узнаваемому крепкому и плотному вкусу. Традиционный способ подачи — через маленький металлический фильтр фин: кофе капает медленно, по капле, и это неспешное ожидание — часть ритуала, а не недостаток.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/kapibary-i-kofe-nyachang/3.png | Капибару угощают фруктами и печеньем с руки]

Получается редкое сочетание: с одной стороны — самое медленное, самое философски-спокойное животное в мире, с другой — напиток, который тоже не терпит спешки. Хорошая точка, чтобы за первые полчаса тура сразу выдохнуть и переключиться на вьетнамский темп жизни.$body1$),

  ('bashnya-kuang-min', 'Золотая башня Куанг Минь: новый ориентир над Нячангом',
   '13-ярусная золотая пагода на горе Фыонг Хоанг — один из самых молодых и самых высоких буддийских комплексов Вьетнама.',
   'https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashnya-kuang-min/1.png',
$body2$На горе Фыонг Хоанг («гора Феникса»), которая возвышается над Нячангом с северо-запада, в последние годы вырос совсем новый буддийский комплекс — Тхап Куанг Минь, золотая 13-ярусная башня-пагода. Это часть волны масштабного храмового строительства, прокатившейся по Вьетнаму в 2010–2020-е: похожие по духу мегакомплексы появились под Ханоем и в Нинь Биня, но именно этот стоит на вершине горы прямо над заливом — с видом сразу на город, бухту, острова и побережье на десятки километров вперёд.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashnya-kuang-min/1.png | Золотая башня Куанг Минь на вершине горы Фыонг Хоанг, вид сверху]

13 ярусов — не случайное число: в буддийской традиции ступы с нечётным количеством уровней (7, 9, 13) считаются наиболее гармоничными, а сама форма многоярусной башни символизирует путь духовного восхождения — от земного к просветлению. Внизу, у подножия башни, расположены традиционные залы с резными крышами в характерном для Вьетнама стиле — с загнутыми вверх «драконьими» углами.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashnya-kuang-min/2.png | Комплекс Куанг Минь с высоты: башня, храмовые залы и лестница среди зелени]

Внутри залов — алтари с позолоченными статуями Будды, перед которыми и сегодня оставляют подношения: фрукты, цветы, благовония. Несмотря на то что комплекс совсем новый по вьетнамским меркам, он уже стал местом, куда приезжают не только туристы, но и местные жители — для многих нячангцев это теперь такая же точка на карте города, как старые пагоды, которым больше ста лет.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashnya-kuang-min/3.png | Алтарь с позолоченными статуями Будды внутри храмового зала]

Смотровая площадка у башни — одна из лучших в Нячанге: отсюда город виден целиком, от прибрежных многоэтажек до дальних островов в бухте, а сама золотая крыша хорошо заметна с моря — теперь это часть силуэта города, узнаваемого не хуже пагоды Лонгшон.$body2$),

  ('pagoda-longshon', 'Пагода Лонгшон и Белый Будда: главный символ Нячанга',
   'Гигантская статуя на холме, лежащий Будда и 152 ступени — история пагоды, которую видно с любой точки города.',
   'https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/pagoda-longshon/1.jpg',
$body3$Пагода Лонгшон была основана ещё в конце XIX века, но своим самым узнаваемым обликом обязана XX веку: в 1963 году на холме позади главного храма установили гигантскую белую статую сидящего Будды — её видно практически из любой точки Нячанга, и для многих гостей города именно этот силуэт на холме и есть первый образ Нячанга. У подножия статуи есть памятная стела в честь буддийских монахов, которые в том же 1963 году открыто протестовали против религиозных притеснений того времени, — эта страница истории до сих пор часть смысла места, а не просто красивый постамент.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/pagoda-longshon/1.jpg | Белый Будда на закате с видом на город и горы]

К статуе ведёт лестница в 152 ступени — подъём несложный, но у него есть смысл: по пути через каждые несколько десятков ступеней открываются новые ракурсы на город, бухту и рисовые пригороды на горизонте, так что дорога наверх сама по себе часть впечатления, а не просто способ добраться до фотографии.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/pagoda-longshon/2.png | Аэрофотоснимок статуи Будды на холме над Нячангом]

Помимо сидящей статуи на холме, в комплексе пагоды есть ещё одна работа современных мастеров — лежащий Будда (поза «паринирваны», ухода в высшее успокоение), вырезанный из светлого камня с мелкой резьбой по драпировкам одежд и целой галереей барельефных лиц вдоль постамента. В отличие от статуи на холме, эта скульптура находится на уровне земли, в тени деревьев — контраст масштаба и настроения хорошо чувствуется, если посмотреть на обе статуи в один день.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/pagoda-longshon/3.jpg | Лежащий Будда с резными барельефами у подножия пагоды]

Сам нижний храм пагоды, у подножия холма, — действующий, там продолжается монашеская жизнь и ежедневные службы; шум города сюда почти не долетает, и это одна из немногих точек тура, где стоит просто немного постоять в тишине, прежде чем ехать дальше.$body3$),

  ('bashni-po-nagar', 'Башни По Нагар: наследие древнего царства Тямпа',
   'Кирпичные башни VII–XIII веков, которым поклоняются до сих пор — и откуда у Нячанга взялось его имя.',
   'https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashni-po-nagar/1.png',
$body4$Задолго до того как здесь появился современный курортный город, эти земли принадлежали царству Тямпа — индуистской цивилизации, которая контролировала центральное побережье Вьетнама с II по XVII век. Башни По Нагар на холме Кулао, у устья реки Кай, строились в несколько этапов между VII и XIII веками — из красного кирпича, без раствора, по технологии, секрет которой до конца не разгадан до сих пор. Кстати, само имя города «Нячанг» — искажённое тямское «Ya Trang», «река тростника»: так тямы называли реку, в устье которой стоят башни.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashni-po-nagar/1.png | Резной барельеф на кирпичной стене башни По Нагар]

Из первоначальных построек до наших дней уцелели четыре башни (когда-то их было больше). Главная, самая высокая — посвящена богине Инь По Нагар, «матери земли» в тямской мифологии, покровительнице урожая и ремёсел. Позже, когда регион перешёл под вьетнамский контроль, богиню не забыли и не заменили — вьетнамцы стали почитать её под именем Тхиен И Ана Тхань Мау, и башни остаются действующим местом поклонения одновременно для тямов-индуистов и для вьетнамцев уже больше тысячи лет — редкий случай непрерывной религиозной преемственности через смену эпох и народов.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashni-po-nagar/2.png | Главная башня По Нагар анфас, в обрамлении деревьев]

На стенах и нишах башен сохранились резные фигуры божеств и танцовщиц, похожие по стилю на кхмерский Ангкор — Тямпа и Кхмерская империя были соседями и во многом делили общую индуистскую традицию. Внутри главной башни до сих пор стоит статуя богини с восемью руками, а перед входом иногда можно застать традиционные тямские танцы и музыку — комплекс не музей под открытым небом, а живое святилище.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/bashni-po-nagar/3.png | Комплекс По Нагар на закате, вид с высоты на реку и город]

С холма, на котором стоят башни, открывается вид на устье реки Кай, рыбацкие лодки и мост, соединяющий старый Нячанг с новыми районами — контраст тысячелетних кирпичных построек и современного города здесь особенно заметен на закате, когда кирпич башен становится совсем медовым на солнце.$body4$),

  ('muzey-aleksandra-yersena', 'Александр Йерсен: учёный, которого Нячанг называет своим',
   'Швейцарский бактериолог открыл возбудителя чумы — и полжизни прожил и работал в Нячанге, где его до сих пор помнят и любят.',
   'https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/muzey-aleksandra-yersena/1.png',
$body5$Александр Йерсен (1863–1943) — швейцарский и французский врач-бактериолог, ученик Луи Пастера, который в 1894 году в Гонконге открыл возбудителя чумы (позже названного в его честь Yersinia pestis) — открытие, которое в итоге позволило создать лекарства и остановить одну из самых страшных эпидемий в истории человечества. Но по-настоящему домом для него стал не Гонконг и не родная Европа, а именно Нячанг, куда он приехал вскоре после своего открытия и где прожил почти полвека — до самой смерти.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/muzey-aleksandra-yersena/1.png | Здание Института Пастера в Нячанге, основанного Йерсеном, с высоты]

В Нячанге Йерсен основал местное отделение Института Пастера и занимался далеко не только чумой: он привёз и акклиматизировал в горах Вьетнама хинное дерево (источник хинина — лекарства от малярии) и каучуковое дерево, изучал метеорологию, астрономию и сельское хозяйство. Местные жители называли его уважительно «ông Năm» — «господин Пятый» (по номеру в неформальной иерархии уважаемых людей города), и это прозвище говорит само за себя: для Нячанга он был не заезжим колониальным чиновником, а своим.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/muzey-aleksandra-yersena/2.png | Личный кабинет Йерсена: телескоп, старинная мебель и приборы, сохранённые в музее]

Сегодня в доме, где он жил и работал, открыт музей — в нём сохранены его телескоп, лабораторные приборы, библиотека и личные вещи. Экспозиция показывает удивительную разносторонность одного человека: врач, бактериолог, ботаник, метеоролог и астроном-любитель в одном лице, до последних дней продолжавший работать в маленьком приморском городе, хотя мог бы вернуться в любую европейскую столицу.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/muzey-aleksandra-yersena/3.jpg | Основные вехи жизни Александра Йерсена]

Йерсен похоронен неподалёку, на горе Хон Ба, по собственному завещанию — рядом с людьми и местом, которому посвятил жизнь. Каждый год в день его смерти жители Нячанга до сих пор приходят к могиле почтить его память — редкий пример иностранца, ставшего частью локальной идентичности вьетнамского города на сто с лишним лет вперёд.$body5$),

  ('hon-chong', 'Хон Чонг: скалы, за которыми стоит легенда',
   'Гранитный мыс с «отпечатком великана» — и история о том, почему один камень называют «мужем», а соседний островок — «женой».',
   'https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/hon-chong/1.png',
$body6$Хон Чонг — гранитный мыс на северной окраине Нячанга, где море за тысячелетия отполировало и нагромоздило друг на друга огромные валуны причудливой формы. Название переводится примерно как «нагромождённые камни», но у вьетнамцев есть куда более красивая версия происхождения этого места — старая легенда о великане.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/hon-chong/1.png | Балансирующий валун с характерным отпечатком у мыса Хон Чонг]

По легенде, великан пришёл к этим берегам, залюбовался купающимися феями и, оступившись при попытке остаться, схватился за скалу — с тех пор на одном из валунов виден след, похожий на отпечаток огромной ладони. Сам великан, если верить преданию, в отчаянии от несбывшейся любви окаменел неподалёку — так по одной из версий появился и соседний островок Хон Выонг, «Жена», названный не то в пару, не то в противовес мысу Хон Чонг, «Муж».

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/hon-chong/2.png | Мыс Хон Чонг с высоты: валуны, узкая полоса пляжа и лодки в бухте]

Помимо легенды, у Хон Чонга есть и вполне земное достоинство — это одна из лучших смотровых точек Нячанга: с камней открывается панорама на весь залив, остров Хон Че и горную гряду на материке. Восход солнца здесь встречают чаще, чем закат — с утра свет мягко подсвечивает гранит, окрашивая валуны в тёплый охристый цвет, как на классических открытках с видом Нячанга.

Сегодня рядом с мысом работает небольшой культурный павильон, где можно узнать больше о рыбацких традициях и повседневной жизни прибрежных вьетнамских деревень — контраст между древней легендой о великане и вполне обыденной жизнью современных рыбаков у тех же самых скал стоит того, чтобы задержаться здесь чуть дольше одной фотографии.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/hon-chong/3.png | Живое выступление с традиционными вьетнамскими инструментами в культурном павильоне у мыса]

В этом же павильоне иногда проходят живые выступления: музыканты играют на традиционных инструментах — каменных пластинах-ксилофонах дан-да, барабанах и гонгах — в свете красных бумажных фонарей. Если получится застать такое выступление, прогулка по камням превращается в нечто большее, чем фотопауза: несколько минут настоящего местного звучания вместо очередной открытки.$body6$),

  ('obed-v-kafe-s-vertoletom', 'Кафе с вертолётом: необычный обед в Нячанге',
   'Настоящий вертолёт для фото, игуана на веранде и обед над прудом с карпами кои — гастро-остановка, которая сама по себе аттракцион.',
   'https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/obed-v-kafe-s-vertoletom/1.png',
$body7$В программе тура обед — не просто пауза для еды, а ещё одна остановка, которая запоминается не хуже храмов и башен. Это кафе в Нячанге совмещает несколько неожиданных вещей сразу: у входа гостей встречает настоящий небольшой вертолёт, установленный на террасе как декорация, — в него можно сесть и сделать фотографию, будто вы только что приземлились с воздушной экскурсии над бухтой.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/obed-v-kafe-s-vertoletom/1.png | Настоящий вертолёт на террасе кафе — можно сесть внутрь для фото]

Пока еда готовится, на веранде можно познакомиться с местным «сотрудником» — ручной игуаной, которая привыкла к посетителям и спокойно берёт угощение из рук. Для многих гостей это первая в жизни встреча с крупной рептилией так близко и без стекла вольера — неожиданно спокойное и совсем не пугающее знакомство.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/obed-v-kafe-s-vertoletom/2.png | Игуану кормят овощами прямо с рук на веранде кафе]

Столики в кафе расположены прямо у пруда с карпами кои — крупными, разноцветными, привыкшими подплывать к краю в ожидании корма. Такой формат — обед у воды с рыбой, а не просто «вид на бассейн» — вообще характерен для нового поколения тематических кафе в Нячанге, ориентированных в первую очередь на впечатление, а не только на кухню.

[фото: https://our41hywrmbsqagk.public.blob.vercel-storage.com/articles/nyachang/obed-v-kafe-s-vertoletom/3.png | Столики кафе на террасе прямо над прудом с яркими карпами кои]

Меню при этом вполне обычное вьетнамское — гости выбирают блюда сами и оплачивают заказ по факту, без ограничений программы тура. Получается редкий случай, когда рядовой обед в середине насыщенного дня превращается в отдельный маленький пункт впечатлений — с фотографиями, которые потом пересматривают чаще, чем снимки из храмов.$body7$)

) as v(slug, title, excerpt, cover_image_url, body);
